const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',message:'M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2ZM7 7h10M7 11h7',image:'M3 3h18v18H3ZM3 16l5-5 4 4 4-6 5 8M7 7h.01',calendar:'M3 5h18v16H3ZM3 10h18M8 2v6M16 2v6M7 14h3M14 14h3M7 17h3',external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7',logout:'M9 3H3v18h6M13 7l5 5-5 5M7 12h14',menu:'M3 6h18M3 12h18M3 18h18',plus:'M12 5v14M5 12h14',search:'M21 21l-6-6',filter:'M3 4h18l-7 8v7l-4 2v-9Z',sort:'M8 4v16M4 8l4-4 4 4M16 20V4M12 16l4 4 4-4',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',send:'m21 3-7 18-4-7-7-4 18-7ZM10 14 21 3',edit:'m16 3 5 5-12 12-6 1 1-6 12-12ZM14 5l5 5',more:'M5 12h.01M12 12h.01M19 12h.01',music:'M9 18V5l12-2v13M9 9l12-2'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.image}"/>${name==='users'?'<circle cx="9" cy="7" r="4"/>':name==='search'?'<circle cx="10" cy="10" r="7"/>':name==='music'?'<ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="18" cy="16" rx="3" ry="2"/>':''}</svg>`;}
function icons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
icons();
function notice(message,error=false){$('#notice').hidden=false;$('#notice').dataset.error=error;$('#notice-text').setAttribute('role',error?'alert':'status');$('#notice-text').textContent=message;}
$('#dismiss-notice').onclick=()=>$('#notice').hidden=true;
$$('[data-demo]').forEach(b=>b.onclick=()=>notice(b.dataset.demo));
let opener;
const modal=$('#modal');
function openModal(title,html,focus='button'){opener=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;modal.showModal();(modal.querySelector(`#modal-body ${focus}`)||modal.querySelector('button')).focus();}
modal.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();else $(`#page-${currentPage} h1`)?.focus();});
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function confirmAction(title,text,action,run,danger=false){openModal(title,`<p>${esc(text)}</p><div class="dialog-actions"><button id="cancel-action">Batal</button><button class="${danger?'danger ':''}primary" id="confirm-action">${esc(action)}</button></div>`);$('#cancel-action').onclick=()=>modal.close();$('#confirm-action').onclick=()=>{modal.close();run();};}
let currentPage='tamu';
function route(){const page=location.hash.slice(1)||'tamu';currentPage=['tamu','pesan','media','acara','login'].includes(page)?page:'tamu';$('#app').hidden=currentPage==='login';$('#login-screen').hidden=currentPage!=='login';$$('.page').forEach(s=>s.hidden=s.id!==`page-${currentPage}`);$$('nav a').forEach(a=>{if(a.hash===`#${currentPage}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#nav-dialog').close();document.title=`weddinvita — ${currentPage==='login'?'Masuk':$(`#page-${currentPage} h1`)?.textContent} (studi)`;window.scrollTo(0,0);if(currentPage!=='login')$(`#page-${currentPage} h1`)?.focus({preventScroll:true});}
