$('#login-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button');b.disabled=true;b.textContent='Memeriksa…';$('#login-error').textContent='';setTimeout(()=>{b.disabled=false;b.innerHTML=`Masuk ke akun ${icon('right')}`;$('#login-error').textContent='Simulasi kegagalan: email atau kata sandi belum sesuai. Periksa kembali lalu coba lagi.';},500);};
